pub(crate) const GG_TEAM_MANAGE_BASE_DESCRIPTION: &str = "Provide `remove_agent_ids` (for example [\"agent_1\", \"agent_2\"]) to remove existing members. With that field omitted, this legacy tool only inspects an original keyed Add request using its original caller, team, invocation ID and inputs. Fresh Add requests are unavailable; use workspace-authoritative `gg_team` add. Removed or changed presets may return the original operation as unresolved; this never authorizes native retry.";
pub(crate) const GG_MCP_CALLER_AGENT_ID_ARG_KEY: &str = "__gg_caller_agent_id";
